SELECT a.STOCKSNAME AS `股票名称`, a.STOCKCODE AS `股票代码`, a.ENDDATE AS `日期`, ROUND(a.CHNG_PCT_YEAR_SOFAR, 2) AS `今年以来涨跌幅(%)` FROM ANA_STK_EXPR_IDX a JOIN GET_A_SEC_CODE b ON a.INNER_CODE = b.INNER_CODE WHERE a.STOCKSNAME LIKE '%海康威视%' AND a.ENDDATE = '2026-09-02' AND a.CHNG_PCT_YEAR_SOFAR IS NOT NULL AND b.ISVALID = 1 LIMIT 1;
